#include "l2_slice.hpp"
#include <fstream>
#include <random>
using namespace timing;
unsigned mask(const std::vector<bool>&v){unsigned x=0;for(unsigned i=0;i<v.size();i++)x|=v[i]<<i;return x;}
int main(){L2Slice l2(2,4,2,4,2,2,4);std::mt19937 rng(5091);std::ofstream in("l2_stim.txt"),out("l2_expected.txt");struct Pending{Cycle due;bool write;uint32_t id;};std::deque<Pending> queue;for(unsigned t=0;t<3000;t++){L2Input x(2);for(unsigned s=0;s<2;s++){x.read[s]={bool(rng()%3),t*2+s+1,uint32_t((rng()%32)*32),255};x.write[s]={bool(rng()%4==0),t*2+s+1,uint32_t(65536+(rng()%32)*32),255};x.read_ready[s]=rng()%4!=0;x.write_ready[s]=rng()%4!=0;}x.backing_ready=rng()%4!=0;x.store_ready=rng()%4!=0;if(!queue.empty()&&queue.front().due<=t){if(queue.front().write)x.store_return=queue.front().id;else x.backing_return=queue.front().id;queue.pop_front();}auto y=l2.eval(x);if(y.backing.valid&&x.backing_ready)queue.push_back({t+7,false,y.backing.id});if(y.store.valid&&x.store_ready)queue.push_back({t+3,true,y.store.id});in<<t<<' '<<((x.read[0].valid?1:0)|(x.read[1].valid?2:0))<<' '<<((x.write[0].valid?1:0)|(x.write[1].valid?2:0))<<' '<<mask(x.read_ready)<<' '<<mask(x.write_ready)<<' '<<x.backing_ready<<' '<<x.store_ready<<' '<<bool(x.backing_return)<<' '<<x.backing_return.value_or(0)<<' '<<bool(x.store_return)<<' '<<x.store_return.value_or(0);for(auto p:x.read)in<<' '<<p.id<<' '<<p.address;for(auto p:x.write)in<<' '<<p.id<<' '<<p.address;in<<'\n';out<<t<<' '<<mask(y.read_ready)<<' '<<mask(y.write_ready)<<' '<<mask(y.read_valid)<<' '<<mask(y.write_valid);for(auto id:y.read_id)out<<' '<<id;for(auto id:y.write_id)out<<' '<<id;out<<' '<<y.backing.valid<<' '<<(y.backing.valid?y.backing.id:0)<<' '<<(y.backing.valid?y.backing.address:0)<<' '<<y.store.valid<<' '<<(y.store.valid?y.store.id:0)<<' '<<(y.store.valid?y.store.address:0)<<' '<<(y.store.valid?unsigned(y.store.mask):0)<<' '<<l2.requests<<' '<<l2.hits<<' '<<l2.misses<<' '<<l2.merges<<' '<<l2.fills<<' '<<y.owners<<' '<<y.mshrs<<' '<<l2.peak_owners<<' '<<l2.peak_mshrs<<'\n';l2.edge(x);}}
